/*!
 * SoundFontEngine.ts
 *
 * SoundFont playback backend for a JummBox fork, replacing the built-in
 * wavetable/FM/noise instruments with SF2 / SF3 / DLS sample playback.
 *
 * Design note
 * -----------
 * This deliberately does NOT run in a separate AudioWorklet. JummBox's
 * `Synth.synthesize()` renders in tick-sized chunks inside a single
 * ScriptProcessorNode callback, and it already knows exactly which notes
 * start and stop on each tick. spessasynth_core exposes
 * `process(left, right, startIndex, sampleCount)`, so we can render the
 * soundfont voices into the *same* buffer, at the *same* sub-block offsets.
 *
 * The result is sample-accurate note timing with no scheduling lookahead,
 * no clock drift between two audio graphs, and JummBox's existing per-channel
 * effects chain still sitting downstream if you decide to keep it.
 *
 * Depends on: npm i spessasynth_core
 */

import {
    BasicPreset,
    BasicSoundBank,
    SoundBankLoader,
    SpessaLog,
    SpessaSynthProcessor
} from "spessasynth_core";

/** How far a full pitch-wheel deflection bends, in semitones. */
export const PITCH_BEND_RANGE: number = 24;

/**
 * How many MIDI channels to allocate up front, and per growth step.
 *
 * Growing the channel list requires a processor reset, which stops every note on
 * every channel. Doing that lazily meant the first note of a newly used instrument
 * silenced everything already playing. Allocating a pool ahead of time keeps the
 * common path reset-free.
 */
const CHANNEL_POOL_STEP: number = 24;

const BEND_CENTER: number = 8192;

export interface PresetInfo {
    /** Index into `LoadedFont.presets`; this is what gets serialised in the song. */
    index: number;
    name: string;
    program: number;
    bankMSB: number;
    bankLSB: number;
    isDrum: boolean;
}

export interface LoadedFont {
    /** SHA-256 of the raw file bytes, lowercase hex. Used for de-duplication. */
    id: string;
    /** Human-readable name taken from the SF2 INAM chunk, falling back to the filename. */
    name: string;
    fileName: string;
    byteLength: number;
    presets: PresetInfo[];
    /** The original bytes, retained so the font can be written back into a .jbsf file. */
    data: ArrayBuffer;
}

export interface SlotMix {
    /** Linear gain; 1.0 is unity. */
    gain?: number;
    /** -1 hard left, 0 centre, +1 hard right. */
    pan?: number;
    muted?: boolean;
}

interface Slot {
    /** Index of the underlying spessasynth MIDI channel. */
    midiChannel: number;
    fontId: string | null;
    presetIndex: number;
    gain: number;
    pan: number;
    muted: boolean;
    /** Last bend sent, in semitones, so unchanged ticks cost nothing. */
    lastBend: number;
    /** Last expression sent, as a 0-127 controller value. */
    lastExpression: number;
    /** Whether the previous run produced any signal, including release tails. */
    hadSignal: boolean;
    /** MIDI keys currently held on this slot. Small, so linear scans are fine. */
    sounding: number[];
}

function slotKey(channelIndex: number, instrumentIndex: number): string {
    return channelIndex + ":" + instrumentIndex;
}

export async function sha256Hex(data: ArrayBuffer): Promise<string> {
    const digest: ArrayBuffer = await crypto.subtle.digest("SHA-256", data);
    const bytes: Uint8Array = new Uint8Array(digest);
    let hex: string = "";
    for (let i: number = 0; i < bytes.length; i++) {
        const value: number = bytes[i];
        hex += (value < 16 ? "0" : "") + value.toString(16);
    }
    return hex;
}

export class SoundFontEngine {
    private processor: SpessaSynthProcessor;
    private _sampleRate: number;
    private _maxBlockSize: number;
    private readonly fonts: Map<string, { font: LoadedFont, bank: BasicSoundBank }> = new Map();
    private readonly slots: Map<string, Slot> = new Map();
    /** spessasynth always starts with 16 channels; we grow past that on demand. */
    private allocatedChannels: number;
    /** First channel index we own; everything below is spessasynth's default set. */
    private baseChannel: number = 0;
    private scratchL: Float32Array;
    private scratchR: Float32Array;
    /** One stereo pair per underlying MIDI channel, for per-instrument rendering. */
    private splitOutputs: Float32Array[][] = [];
    private splitEffectsL: Float32Array = new Float32Array(0);
    private splitEffectsR: Float32Array = new Float32Array(0);
    private splitLength: number = 0;
    private readonly initialized: Promise<void>;
    private isReady: boolean = false;

    constructor(sampleRate: number, maxBlockSize: number) {
        this._sampleRate = sampleRate;
        this._maxBlockSize = maxBlockSize;
        this.processor = this.createProcessor();
        this.baseChannel = this.processor.midiChannels.length;
        this.allocatedChannels = this.baseChannel;
        this.growChannelPool();
        this.scratchL = new Float32Array(maxBlockSize);
        this.scratchR = new Float32Array(maxBlockSize);
        this.initialized = this.processor.processorInitialized.then((): void => {
            this.isReady = true;
            // Without this, a busy pattern will steal voices at the default cap.
            this.processor.setSystemParameter("autoAllocateVoices", true);
        });
    }

    private createProcessor(): SpessaSynthProcessor {
        // setLogLevel is (info, warn, group) -- there is no error channel to keep, so
        // all three go off. Otherwise every font import prints a parse trace, and the
        // default percussion channel warns about a missing preset on every song: we
        // never use it, because presets are assigned directly rather than by program.
        SpessaLog.setLogLevel(false, false, false);
        const processor: SpessaSynthProcessor = new SpessaSynthProcessor(this._sampleRate, {
            maxBufferSize: this._maxBlockSize,
            // We drive everything from JummBox, so we don't need the event system.
            eventsEnabled: false,
            // Spessa's own reverb and chorus are off: JummBox's per-instrument effect
            // chain provides those now, and running both would double up.
            effectsEnabled: false
        });
        processor.onMissingPreset = (): undefined => undefined;
        return processor;
    }

    /** True once the processor is safe to render from. Cheap enough for the audio callback. */
    public get ready(): boolean {
        return this.isReady;
    }

    /** Resolves once the SF3 (Vorbis) decoder and the processor are ready. */
    public whenReady(): Promise<void> {
        return this.initialized;
    }

    // ---------------------------------------------------------------- fonts

    /**
     * Parses a soundfont and registers it. Safe to call with a font that is
     * already loaded — the existing entry is returned and nothing is re-parsed.
     */
    public async loadFont(data: ArrayBuffer, fileName: string): Promise<LoadedFont> {
        await this.initialized;
        const id: string = await sha256Hex(data);
        const existing = this.fonts.get(id);
        if (existing != null) return existing.font;

        // SoundBankLoader takes ownership of the buffer's contents, so parse a copy
        // and keep the pristine original for re-export.
        const bank: BasicSoundBank = SoundBankLoader.fromArrayBuffer(data.slice(0));

        const presets: PresetInfo[] = bank.presets.map((preset: BasicPreset, index: number): PresetInfo => ({
            index: index,
            name: preset.name,
            program: preset.program,
            bankMSB: preset.bankMSB,
            bankLSB: preset.bankLSB,
            isDrum: preset.isGMGSDrum || preset.bankMSB === 128
        }));

        const font: LoadedFont = {
            id: id,
            name: bank.soundBankInfo?.name || fileName.replace(/\.[^.]+$/, ""),
            fileName: fileName,
            byteLength: data.byteLength,
            presets: presets,
            data: data
        };

        // Registering with the manager keeps sample data alive and lets spessa
        // resolve presets normally if you ever want bank/program selection too.
        this.processor.soundBankManager.addSoundBank(bank, id);
        this.fonts.set(id, { font: font, bank: bank });

        // addSoundBank resets the controller state of EVERY channel, which silently
        // throws away the pitch bend range and puts it back to the MIDI default of 2
        // semitones. So this reconfigures every slot, not just the ones waiting on
        // this font -- and that also resolves any slot that named the font before its
        // bytes had arrived.
        for (const slot of this.slots.values()) {
            this.configureChannel(slot);
        }
        return font;
    }

    /**
     * Loads the tiny saw-wave bank bundled with spessasynth_core. It exists so that
     * playback can be verified without shipping or picking a real soundfont.
     */
    public loadBuiltInTestFont(): Promise<LoadedFont> {
        return this.loadFont(BasicSoundBank.getSampleSoundBankFile(), "spessasynth-sample.sf2");
    }

    public getFont(id: string): LoadedFont | null {
        return this.fonts.get(id)?.font ?? null;
    }

    public listFonts(): LoadedFont[] {
        return Array.from(this.fonts.values()).map((entry): LoadedFont => entry.font);
    }

    /** Unloads a font and clears any slot still pointing at it. */
    public unloadFont(id: string): void {
        if (!this.fonts.has(id)) return;
        for (const slot of this.slots.values()) {
            if (slot.fontId === id) {
                slot.fontId = null;
                this.processor.midiChannels[slot.midiChannel].preset = undefined;
            }
        }
        this.processor.soundBankManager.deleteSoundBank(id);
        this.fonts.delete(id);
        this.processor.clearCache();
        // Same reasoning as loadFont: changing the bank stack resets channel state.
        for (const slot of this.slots.values()) {
            this.configureChannel(slot);
        }
    }

    /** Total bytes of all loaded fonts — useful for warning before an export. */
    public totalFontBytes(): number {
        let total: number = 0;
        for (const entry of this.fonts.values()) total += entry.font.byteLength;
        return total;
    }

    // ---------------------------------------------------------------- slots

    private getSlot(channelIndex: number, instrumentIndex: number): Slot {
        const key: string = slotKey(channelIndex, instrumentIndex);
        let slot: Slot | undefined = this.slots.get(key);
        if (slot != null) return slot;

        // spessasynth has no hard channel limit, so one MIDI channel per
        // (JummBox channel, instrument) pair is fine even on a large song.
        if (this.allocatedChannels >= this.processor.midiChannels.length) {
            this.growChannelPool();
        }
        const midiChannel: number = this.allocatedChannels;
        this.allocatedChannels++;

        slot = { midiChannel: midiChannel, fontId: null, presetIndex: 0, gain: 1.0, pan: 0.0, muted: false, sounding: [], lastBend: 0.0, lastExpression: -1, hadSignal: false };
        this.slots.set(key, slot);
        this.configureChannel(slot);
        return slot;
    }

    /**
     * Adds channels to the pool and reinitialises controller state.
     *
     * A freshly created channel's controller table is all zeroes, which means CC7
     * volume is 0 and the channel renders total silence with no error and a rising
     * voice count. Only processor.reset() loads the MIDI defaults, and it does so for
     * every channel at once -- which also stops every sounding note. So the `sounding`
     * bookkeeping has to be cleared to match, or those keys are recorded as held
     * forever and never retrigger.
     */
    private growChannelPool(): void {
        const target: number = this.processor.midiChannels.length + CHANNEL_POOL_STEP;
        while (this.processor.midiChannels.length < target) {
            this.processor.createMIDIChannel();
        }
        this.processor.reset();
        for (const slot of this.slots.values()) {
            slot.sounding.length = 0;
            this.configureChannel(slot);
        }
        this.splitOutputs = [];
    }

    /**
     * Repairs a channel whose state has been reset behind our back.
     *
     * Several library operations reset the controller table of every channel --
     * adding or removing a sound bank is one -- which silently drops the pitch bend
     * range back to the MIDI default of 2 semitones. The symptom is that slides bend
     * a twelfth of the distance they should, with no error anywhere. The bend range
     * doubles as a canary for the rest of the channel's state, and the check is one
     * property comparison per tick.
     */
    private ensureChannelState(slot: Slot): void {
        const channel = this.processor.midiChannels[slot.midiChannel];
        if (channel.midiParameters.pitchWheelRange != PITCH_BEND_RANGE) {
            this.configureChannel(slot);
        }
    }

    /** Applies a slot's full state to its underlying MIDI channel. */
    private configureChannel(slot: Slot): void {
        const midiChannel: number = slot.midiChannel;
        const channel = this.processor.midiChannels[midiChannel];
        // We assign presets directly rather than via program change, so lock the
        // channel's patch to stop anything else reassigning it.
        channel.setSystemParameter("presetLock", true);
        // Widen the bend range; JummBox pitch pins routinely exceed +/- 2 semitones.
        // Sent as RPN 0 rather than through the internal setter, to stay on public API.
        this.processor.controllerChange(midiChannel, 101, 0);
        this.processor.controllerChange(midiChannel, 100, 0);
        this.processor.controllerChange(midiChannel, 6, PITCH_BEND_RANGE);
        this.processor.controllerChange(midiChannel, 38, 0);
        channel.setSystemParameter("gain", slot.gain);
        channel.setSystemParameter("pan", slot.pan);
        channel.setSystemParameter("isMuted", slot.muted);
        this.processor.pitchWheel(midiChannel, BEND_CENTER);
        slot.lastBend = 0.0;
        slot.lastExpression = -1;

        if (slot.fontId != null) {
            const entry = this.fonts.get(slot.fontId);
            if (entry != null) {
                channel.preset = entry.bank.presets[slot.presetIndex] || entry.bank.presets[0];
            }
        }
    }

    public get sampleRate(): number {
        return this._sampleRate;
    }

    public get maxBlockSize(): number {
        return this._maxBlockSize;
    }

    /**
     * Rebuilds the underlying processor at a new sample rate or block size,
     * re-registering every loaded font and restoring every slot. Fonts are not
     * re-parsed, so this is cheap.
     */
    public retarget(sampleRate: number, maxBlockSize: number): void {
        const oldProcessor: SpessaSynthProcessor = this.processor;
        this._sampleRate = sampleRate;
        this._maxBlockSize = Math.max(maxBlockSize, this._maxBlockSize);
        this.isReady = false;
        this.scratchL = new Float32Array(this._maxBlockSize);
        this.scratchR = new Float32Array(this._maxBlockSize);
        this.splitOutputs = [];

        this.processor = this.createProcessor();
        for (const entry of this.fonts.values()) {
            this.processor.soundBankManager.addSoundBank(entry.bank, entry.font.id);
        }
        // Slots were allocated sequentially, and Map preserves insertion order,
        // so replaying them in order reproduces the same channel indices.
        this.baseChannel = this.processor.midiChannels.length;
        this.allocatedChannels = this.baseChannel + this.slots.size;
        while (this.processor.midiChannels.length < this.allocatedChannels + CHANNEL_POOL_STEP) {
            this.processor.createMIDIChannel();
        }
        this.processor.reset();
        let index: number = this.baseChannel;
        for (const slot of this.slots.values()) {
            slot.midiChannel = index++;
            slot.sounding.length = 0;
            this.configureChannel(slot);
        }
        this.processor.processorInitialized.then((): void => {
            this.isReady = true;
            this.processor.setSystemParameter("autoAllocateVoices", true);
        });
        oldProcessor.destroySynthProcessor();
    }

    /**
     * Points a JummBox (channel, instrument) pair at a preset in a loaded font.
     * Pass `fontId: null` to silence the slot.
     */
    public assignSlot(channelIndex: number, instrumentIndex: number, fontId: string | null, presetIndex: number): void {
        const slot: Slot = this.getSlot(channelIndex, instrumentIndex);
        if (slot.fontId === fontId && slot.presetIndex === presetIndex) return;

        // Changing sound mid-note leaves orphaned voices, so cut them first.
        this.allNotesOffForSlot(slot, true);

        slot.fontId = fontId;
        slot.presetIndex = presetIndex;

        const channel = this.processor.midiChannels[slot.midiChannel];
        if (fontId == null) {
            channel.preset = undefined;
            return;
        }
        const entry = this.fonts.get(fontId);
        if (entry == null) {
            channel.preset = undefined;
            return;
        }
        channel.preset = entry.bank.presets[presetIndex] ?? entry.bank.presets[0];
    }

    public setSlotMix(channelIndex: number, instrumentIndex: number, mix: SlotMix): void {
        const slot: Slot = this.getSlot(channelIndex, instrumentIndex);
        if (mix.gain != null) slot.gain = mix.gain;
        if (mix.pan != null) slot.pan = mix.pan;
        if (mix.muted != null) slot.muted = mix.muted;
        const channel = this.processor.midiChannels[slot.midiChannel];
        channel.setSystemParameter("gain", slot.gain);
        channel.setSystemParameter("pan", slot.pan);
        channel.setSystemParameter("isMuted", slot.muted);
    }

    // ---------------------------------------------------------------- notes

    /**
     * @param key MIDI note number. Convert from JummBox pitch with
     *            `pitch + channelOctave * 12 + Config.keys[song.key].basePitch`.
     * @param velocity 0-127.
     */
    public noteOn(channelIndex: number, instrumentIndex: number, key: number, velocity: number): void {
        const slot: Slot = this.getSlot(channelIndex, instrumentIndex);
        if (slot.fontId == null) return;
        const midiKey: number = key | 0;
        this.processor.noteOn(slot.midiChannel, midiKey, Math.max(1, Math.min(127, velocity | 0)));
        this.sendBend(slot, midiKey, slot.lastBend);
        if (slot.sounding.indexOf(midiKey) < 0) slot.sounding.push(midiKey);
    }

    /**
     * Reconciles the set of keys held on a slot against `keys[0..count)`, sending
     * note-on for anything new and note-off for anything that has gone away.
     *
     * Driving playback by diffing rather than by intercepting note starts and ends
     * means every way a JummBox tone can disappear -- seamless transitions, chord
     * changes, strumming, tone stealing, pattern boundaries, a channel being muted,
     * the playhead jumping -- results in a note-off automatically. There is no
     * transition that can strand a voice, because a stranded voice would have to be
     * a key that is still in `sounding` but no longer in `keys`, which is exactly
     * what this loop cannot leave behind.
     *
     * @param keys scratch array of MIDI keys; only the first `count` entries are read.
     * @param velocities parallel array, only read when a key is newly starting.
     */
    public updateSoundingKeys(channelIndex: number, instrumentIndex: number, keys: number[], velocities: number[], count: number): void {
        const slot: Slot = this.getSlot(channelIndex, instrumentIndex);
        this.ensureChannelState(slot);
        const sounding: number[] = slot.sounding;

        for (let i: number = sounding.length - 1; i >= 0; i--) {
            const key: number = sounding[i];
            let stillWanted: boolean = false;
            for (let j: number = 0; j < count; j++) {
                if (keys[j] == key) {
                    stillWanted = true;
                    break;
                }
            }
            if (!stillWanted) {
                // Deliberately NOT recentring this key's bend here. A tone is released
                // slightly before its note ends and keeps ringing through the
                // soundfont's release envelope, so centring on note-off snapped the
                // tail of every slide back to the unbent pitch. Correctness comes from
                // note-on always setting the bend instead.
                this.processor.noteOff(slot.midiChannel, key);
                sounding.splice(i, 1);
            }
        }

        if (slot.fontId == null) return;

        for (let j: number = 0; j < count; j++) {
            const key: number = keys[j];
            let alreadySounding: boolean = false;
            for (let i: number = 0; i < sounding.length; i++) {
                if (sounding[i] == key) {
                    alreadySounding = true;
                    break;
                }
            }
            if (alreadySounding) continue;
            this.processor.noteOn(slot.midiChannel, key, Math.max(1, Math.min(127, velocities[j] | 0)));
            // Always send the bend, even when it is zero.
            //
            // Per-note pitch bend is stored per key ON THE CHANNEL and outlives the
            // note that used it. Skipping this when the bend is zero left any key
            // that had been bent by an earlier slide permanently detuned: the next
            // note on that key inherited the old bend, and bendAllSounding() would
            // not correct it because from its point of view nothing had changed.
            this.sendBend(slot, key, slot.lastBend);
            sounding.push(key);
        }
    }

    /**
     * Reports how the assigned preset will treat a given key: which zones match, and
     * the tuning generators that decide the resulting pitch. This exists to tell
     * "we sent the wrong key" apart from "the font maps this key that way", which
     * sound identical from the outside.
     */
    public describeKey(channelIndex: number, instrumentIndex: number, key: number): string {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null || slot.fontId == null) return "key " + key + ": no font assigned";
        const entry = this.fonts.get(slot.fontId);
        if (entry == null) return "key " + key + ": font not loaded";
        const preset: BasicPreset | undefined = entry.bank.presets[slot.presetIndex];
        if (preset == null) return "key " + key + ": no preset";

        const parts: string[] = [];
        for (const presetZone of preset.zones) {
            if (presetZone.hasKeyRange && (key < presetZone.keyRange.min || key > presetZone.keyRange.max)) continue;
            for (const zone of presetZone.instrument.zones) {
                if (zone.hasKeyRange && (key < zone.keyRange.min || key > zone.keyRange.max)) continue;
                // 58 overridingRootKey, 56 scaleTuning, 51 coarseTune, 52 fineTune.
                const gen = (type: number, fallback: number): number => {
                    for (const g of zone.generators) if (g.type === type) return g.value;
                    return fallback;
                };
                const root: number = gen(58, -1);
                const scale: number = gen(56, 100);
                const sample = zone.sample;
                parts.push(
                    "sample=" + sample.name +
                    " root=" + (root >= 0 ? root + " (overridden)" : sample.originalKey) +
                    " scaleTuning=" + scale +
                    " coarse=" + gen(51, 0) +
                    " fine=" + gen(52, 0) +
                    " pitchCorr=" + sample.pitchCorrection +
                    " rate=" + sample.sampleRate
                );
            }
        }
        if (parts.length === 0) return "key " + key + ": NO ZONE MATCHES (key outside the preset's range - silent)";
        return "key " + key + ": " + parts.join(" | ");
    }

    /**
     * A full report for one slot: what preset is loaded, what the channel's live MIDI
     * state actually is, and how the font maps a range of keys. Intended to be read
     * by a human when something sounds wrong.
     */
    public diagnose(channelIndex: number, instrumentIndex: number, lowKey: number = 60, highKey: number = 72): string {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return "channel " + channelIndex + " instrument " + instrumentIndex + ": no slot allocated";
        const lines: string[] = [];
        lines.push("channel " + (channelIndex + 1) + ", instrument " + (instrumentIndex + 1) + " -> MIDI channel " + slot.midiChannel);
        const font: LoadedFont | null = slot.fontId != null ? this.getFont(slot.fontId) : null;
        lines.push("font: " + (font != null ? font.name + " (" + font.fileName + ")" : "NONE"));
        if (font != null) {
            const info: PresetInfo | undefined = font.presets[slot.presetIndex];
            lines.push("preset " + slot.presetIndex + ": " + (info != null ? info.name + (info.isDrum ? "  [DRUM PRESET - keys are kit pieces, not pitches]" : "") : "MISSING"));
        }
        const channel = this.processor.midiChannels[slot.midiChannel];
        lines.push("pitch wheel range: " + channel.midiParameters.pitchWheelRange + " semitones (expected " + PITCH_BEND_RANGE + ")");
        lines.push("last bend sent: " + slot.lastBend.toFixed(3) + " semitones | last expression: " + slot.lastExpression + "/127");
        lines.push("keys held: " + (slot.sounding.length > 0 ? slot.sounding.join(", ") : "none"));
        lines.push("");
        for (let key: number = lowKey; key <= highKey; key++) {
            lines.push(this.describeKey(channelIndex, instrumentIndex, key));
        }
        return lines.join("\n");
    }

    /** True while the slot is holding at least one key. */
    public hasSoundingNotes(channelIndex: number, instrumentIndex: number): boolean {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        return slot != null && slot.sounding.length > 0;
    }

    /**
     * True while the slot is holding keys *or* still producing sound from them.
     *
     * The distinction matters. A JummBox instrument goes silent the moment its tones
     * end, because the tone itself renders the fade-out. A soundfont voice keeps
     * ringing after note-off under its own release envelope, so the instrument has to
     * stay open for it -- otherwise the release tail is cut off the instant the key
     * lifts. Uses the previous run's signal, which lags by one tick and is harmless.
     */
    public isSlotActive(channelIndex: number, instrumentIndex: number): boolean {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return false;
        return slot.sounding.length > 0 || slot.hadSignal;
    }

    public noteOff(channelIndex: number, instrumentIndex: number, key: number): void {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return;
        const midiKey: number = key | 0;
        this.processor.noteOff(slot.midiChannel, midiKey);
        const index: number = slot.sounding.indexOf(midiKey);
        if (index >= 0) slot.sounding.splice(index, 1);
    }

    /**
     * Per-note pitch bend, so two notes of a chord can slide independently —
     * which regular channel-wide MIDI bend cannot express.
     * @param semitones offset from `key`, may be fractional.
     */
    public bendNote(channelIndex: number, instrumentIndex: number, key: number, semitones: number): void {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return;
        this.sendBend(slot, key | 0, semitones);
    }

    private sendBend(slot: Slot, key: number, semitones: number): void {
        const clamped: number = Math.max(-PITCH_BEND_RANGE, Math.min(PITCH_BEND_RANGE, semitones));
        const value: number = Math.round(BEND_CENTER + (clamped / PITCH_BEND_RANGE) * BEND_CENTER);
        this.processor.pitchWheel(slot.midiChannel, Math.max(0, Math.min(16383, value)), key);
    }

    /**
     * Applies one bend, in semitones, to every key currently held on the slot.
     *
     * This uses per-note pitch wheel rather than the channel wheel. It costs no more
     * here, and it leaves the door open for chord tones that bend independently,
     * which plain channel-wide MIDI bend cannot express.
     */
    public bendAllSounding(channelIndex: number, instrumentIndex: number, semitones: number): void {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return;
        // A bend is only worth re-sending when it actually moved. Held notes with no
        // pitch pins are the common case, and they should cost nothing per tick.
        if (Math.abs(semitones - slot.lastBend) < 0.0005) return;
        slot.lastBend = semitones;
        for (let i: number = 0; i < slot.sounding.length; i++) {
            this.sendBend(slot, slot.sounding[i], semitones);
        }
    }

    /**
     * Sets the slot's volume to a *linear gain*, via CC11 expression.
     *
     * CC11 is not linear: measured against spessasynth, gain is exactly
     * (cc / 127)^2, so the controller value is the square root of the target.
     * Passing the gain rather than a raw controller value keeps that conversion in
     * one place and lets the caller think purely in JummBox terms.
     *
     * @param gain 0.0 to 1.0, linear.
     */
    public setExpressionGain(channelIndex: number, instrumentIndex: number, gain: number): void {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null) return;
        const clamped: number = Math.max(0.0, Math.min(1.0, gain));
        const value: number = Math.max(0, Math.min(127, Math.round(Math.sqrt(clamped) * 127)));
        if (value == slot.lastExpression) return;
        slot.lastExpression = value;
        this.processor.controllerChange(slot.midiChannel, 11, value);
    }

    private allNotesOffForSlot(slot: Slot, force: boolean): void {
        // CC123 = All Notes Off (release), CC120 = All Sound Off (immediate).
        this.processor.controllerChange(slot.midiChannel, force ? 120 : 123, 0);
        if (force) {
            // Only safe when the sound is cut outright; on a soft release the tails
            // are still ringing and would jump pitch.
            for (let i: number = 0; i < slot.sounding.length; i++) {
                this.sendBend(slot, slot.sounding[i], 0.0);
            }
        }
        slot.sounding.length = 0;
        slot.lastBend = 0.0;
    }

    /** Call on stop/pause. `force` cuts tails immediately instead of releasing them. */
    public allNotesOff(force: boolean = false): void {
        this.processor.stopAllChannels(force);
        for (const slot of this.slots.values()) {
            if (force) {
                for (let i: number = 0; i < slot.sounding.length; i++) {
                    this.sendBend(slot, slot.sounding[i], 0.0);
                }
            }
            slot.sounding.length = 0;
            slot.lastBend = 0.0;
        }
    }

    // --------------------------------------------------------------- render

    /**
     * Adds `length` samples of soundfont audio into `left`/`right` at `offset`.
     * Note that spessasynth accumulates into the buffers rather than overwriting
     * them, so the caller is responsible for whatever was already there.
     */
    /**
     * Renders the soundfont voices and *adds* them into `left`/`right`.
     * Use this while JummBox's own instruments still write to the same buffer,
     * and place the call before the master limiter so the output is limited too.
     */
    public mixInto(left: Float32Array, right: Float32Array, offset: number, length: number): void {
        if (this.scratchL.length < length) {
            this.scratchL = new Float32Array(length);
            this.scratchR = new Float32Array(length);
        }
        const scratchL: Float32Array = this.scratchL;
        const scratchR: Float32Array = this.scratchR;
        // Required: render() accumulates rather than overwriting.
        scratchL.fill(0.0, 0, length);
        scratchR.fill(0.0, 0, length);
        this.render(scratchL, scratchR, 0, length);
        for (let i: number = 0; i < length; i++) {
            left[offset + i] += scratchL[i];
            right[offset + i] += scratchR[i];
        }
    }

    private ensureSplitBuffers(length: number): void {
        const channelCount: number = this.processor.midiChannels.length;
        if (this.splitEffectsL.length >= length && this.splitOutputs.length >= channelCount) return;
        const size: number = Math.max(length, this._maxBlockSize);
        this.splitOutputs = [];
        for (let i: number = 0; i < channelCount; i++) {
            this.splitOutputs.push([new Float32Array(size), new Float32Array(size)]);
        }
        this.splitEffectsL = new Float32Array(size);
        this.splitEffectsR = new Float32Array(size);
    }

    /**
     * Renders every slot into its own buffer so that each JummBox instrument can be
     * put through its own effect chain. Call once per run, then read each slot with
     * addSlotMono(). Rendered audio always starts at index 0 of the slot buffers,
     * regardless of where it will land in the output.
     */
    public renderSplit(length: number): void {
        this.ensureSplitBuffers(length);

        // spessasynth ADDS into the buffers you hand it, it does not overwrite them.
        // Without this clear, every run piles on top of the last and the output grows
        // without bound into a loud drone. Not obvious from the API, and it fails
        // loudly rather than subtly, so it is worth the explicit comment.
        // Only the channels we read need clearing. Unused pool channels have no
        // preset, so they only ever receive silence and stay at zero.
        for (const slot of this.slots.values()) {
            if (slot.midiChannel >= this.splitOutputs.length) continue;
            this.splitOutputs[slot.midiChannel][0].fill(0.0, 0, length);
            this.splitOutputs[slot.midiChannel][1].fill(0.0, 0, length);
        }
        this.splitEffectsL.fill(0.0, 0, length);
        this.splitEffectsR.fill(0.0, 0, length);

        let remaining: number = length;
        let position: number = 0;
        while (remaining > 0) {
            const chunk: number = Math.min(remaining, this._maxBlockSize);
            this.processor.processSplit(this.splitOutputs, this.splitEffectsL, this.splitEffectsR, position, chunk);
            position += chunk;
            remaining -= chunk;
        }
        this.splitLength = length;
    }

    /**
     * Adds a slot's rendered audio, downmixed to mono, into `dest` at `destOffset`.
     * Mono because JummBox's effect chain takes a mono input and produces the stereo
     * image itself through its panning effect.
     * @returns true if the slot produced any signal, which the caller can use to
     *          decide whether the instrument's effects need to keep running.
     */
    public addSlotMono(channelIndex: number, instrumentIndex: number, dest: Float32Array, destOffset: number, length: number): boolean {
        const slot: Slot | undefined = this.slots.get(slotKey(channelIndex, instrumentIndex));
        if (slot == null || slot.midiChannel >= this.splitOutputs.length) return false;
        const pair: Float32Array[] = this.splitOutputs[slot.midiChannel];
        const left: Float32Array = pair[0];
        const right: Float32Array = pair[1];
        const count: number = Math.min(length, this.splitLength);
        let nonZero: boolean = false;
        for (let i: number = 0; i < count; i++) {
            const sample: number = (left[i] + right[i]) * 0.5;
            if (sample != 0.0) nonZero = true;
            dest[destOffset + i] += sample;
        }
        slot.hadSignal = nonZero;
        return nonZero;
    }

    public render(left: Float32Array, right: Float32Array, offset: number, length: number): void {
        let remaining: number = length;
        let position: number = offset;
        while (remaining > 0) {
            const chunk: number = Math.min(remaining, this._maxBlockSize);
            this.processor.process(left, right, position, chunk);
            position += chunk;
            remaining -= chunk;
        }
    }

    public get voiceCount(): number {
        return this.processor.voiceCount;
    }

    public destroy(): void {
        this.processor.destroySynthProcessor();
        this.fonts.clear();
        this.slots.clear();
    }
}
